    private static readonly Dictionary<string, string> NormalizedBadges = new(StringComparer.OrdinalIgnoreCase);
    private static readonly KeyValuePair<string, string>[] PrefixEntries;

    static TeamBadgeCatalog()
    {
        foreach (var (name, url) in ExactBadges)
        {
            var norm = Normalize(name);
            if (norm.Length >= 3)
            {
                NormalizedBadges.TryAdd(norm, url);
            }
        }
        PrefixEntries = [.. NormalizedBadges];
    }

    public static string? ResolveBadge(string? teamName)
    {
        if (string.IsNullOrWhiteSpace(teamName)) return null;
        var trimmed = teamName.Trim();
        if (ExactBadges.TryGetValue(trimmed, out var exact)) return exact;
        var norm = Normalize(trimmed);
        if (norm.Length >= 3 && NormalizedBadges.TryGetValue(norm, out var fromNorm)) return fromNorm;
        if (norm.Length >= 4)
        {
            for (var i = 0; i < PrefixEntries.Length; i++)
            {
                var entry = PrefixEntries[i];
                if (entry.Key.Length >= 4 && (norm.Contains(entry.Key, StringComparison.OrdinalIgnoreCase) || entry.Key.Contains(norm, StringComparison.OrdinalIgnoreCase)))
                {
                    return entry.Value;
                }
            }
        }
        return null;
    }

    public static string Normalize(string input)
    {
        if (string.IsNullOrWhiteSpace(input)) return string.Empty;
        var s = input.Normalize(NormalizationForm.FormD);
        var sb = new StringBuilder(s.Length);
        for (var i = 0; i < s.Length; i++)
        {
            var c = s[i];
            if (CharUnicodeInfo.GetUnicodeCategory(c) == UnicodeCategory.NonSpacingMark) continue;
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9'))
            {
                sb.Append(char.ToLowerInvariant(c));
            }
        }
        var cleaned = sb.ToString();
        cleaned = cleaned
            .Replace("footballclub", "")
            .Replace("fc", "")
            .Replace("cf", "")
            .Replace("sc", "")
            .Replace("rc", "")
            .Replace("aj", "")
            .Replace("estac", "")
            .Replace("stade", "")
            .Replace("sco", "")
            .Replace("29", "")
            .Replace("cd", "")
            .Replace("ud", "")
            .Replace("athletic", "")
            .Replace("club", "")
            .Replace("de", "")
            .Replace("del", "");
        return cleaned;
    }
}
